-- ── 2. data migration from the previous hand-written schema ─────────────────
INSERT INTO "app_user" ("id", "name", "email", "email_verified", "phone_number", "phone_number_verified", "role",
                        "created_at", "updated_at", "account_status", "permission_version")
SELECT u."id"::uuid, u."email", u."email", false,
       CASE WHEN u."phone" ~ '^\+251[79][0-9]{8}$' THEN u."phone" ELSE NULL END, false,
       CASE u."role" WHEN 'RIDER' THEN 'rider' WHEN 'DRIVER' THEN 'driver' WHEN 'ADMIN' THEN 'super_admin' END,
       u."createdAt", u."updatedAt", 'ACTIVE', 1
FROM "User" u;

INSERT INTO "account" ("id", "account_id", "provider_id", "user_id", "password", "created_at", "updated_at")
SELECT uuidv7(), u."id", 'credential', u."id"::uuid, u."passwordHash", u."createdAt", u."updatedAt"
FROM "User" u;

DROP TABLE "User";
DROP TYPE "Role";

-- ── 3. constraints (Database.md §7.1) ───────────────────────────────────────
ALTER TABLE "app_user"
  ADD CONSTRAINT "ck_app_user_phone_e164_et" CHECK ("phone_number" IS NULL OR "phone_number" ~ '^\+251[79][0-9]{8}$'),
  ADD CONSTRAINT "ck_app_user_account_status" CHECK ("account_status" IN ('ACTIVE', 'GUEST', 'DELETED'));

ALTER TABLE "session"
  ADD CONSTRAINT "ck_session_surface" CHECK ("surface" IN ('app', 'admin'));

ALTER TABLE "organization"
  ADD CONSTRAINT "ck_organization_kind" CHECK ("kind" IN ('FLEET', 'CORPORATE', 'STAFF_CITY', 'STAFF_HQ')),
  ADD CONSTRAINT "ck_organization_status" CHECK ("status" IN ('PENDING', 'VERIFIED', 'SUSPENDED'));
CREATE UNIQUE INDEX "ux_organization_kind_tin" ON "organization" ("kind", "tin") WHERE "tin" IS NOT NULL;
-- exactly one staff organisation per city
CREATE UNIQUE INDEX "ux_organization_staff_city" ON "organization" ("city_id") WHERE "kind" = 'STAFF_CITY';

ALTER TABLE "approval_request"
  ADD CONSTRAINT "ck_approval_maker_not_checker" CHECK ("checker_id" IS NULL OR "checker_id" <> "maker_id"),
  ADD CONSTRAINT "ck_approval_status" CHECK ("status" IN ('PENDING', 'APPROVED', 'REJECTED', 'EXECUTED', 'EXPIRED'));

DROP INDEX IF EXISTS "ix_outbox_unpublished";
CREATE INDEX "ix_outbox_unpublished" ON "outbox" ("created_at") WHERE "published_at" IS NULL;

